 setSel('fObra','Todas',vals([...ap,...DATA.fvs,...DATA.movimentosFerramentas],'OBRA'),f.obra);setSel('fPacote','Todos',vals([...ap,...DATA.fvs,...DATA.movimentosFerramentas],'PACOTE_COD'),f.pac);setSel('fPav','Todos',vals([...ap,...DATA.fvs,...DATA.movimentosFerramentas],'PAVIMENTO'),f.pav);setSel('fLocal','Todos',vals([...ap,...DATA.fvs,...DATA.movimentosFerramentas].map(x=>({...x,LOCAL_FRENTE:x.LOCAL_FRENTE||x.LOCAL})),'LOCAL_FRENTE'),f.local);
