function employeeAliases(){const out=[];for(const r of (DATA.config||[])){if(!String(r.CHAVE||'').startsWith('ALIAS_FUNC-'))continue;try{const a=JSON.parse(String(r.VALOR||'{}'));if(a.sourceMat&&a.sourceName&&a.targetMat)out.push(a)}catch{}}return out}
function validationCatalog(){return {funcionarios:DATA.funcionarios||[],pacotes:DATA.pacotes||[],aliases:employeeAliases()}}
async function processFiles(files){if(!files.length)return;const out=$('valResults');out.innerHTML='<div class="loading-card">Validando '+files.length+' arquivo(s)…</div>';validationReports=[];const seenDate=new Map();for(const file of files){try{const rep=await V.parseFile(file,validationCatalog());rep._file=file;for(const d of new Set(rep.apontamentos.map(x=>x.DATA))){if(seenDate.has(d)){rep.ocorrencias.push({SEVERIDADE:'ALERTA',TIPO:'DIA_DUPLICADO_NO_LOTE',DATA:d,ARQUIVO:file.name,DETALHE:'Outro arquivo selecionado também contém '+fmtDate(d)+'.',ACAO:'Confirme qual arquivo representa o dia correto.'});rep.importacao.ALERTAS++;rep.importacao.STATUS='APROVADO_COM_ALERTAS'}else seenDate.set(d,file.name)}validationReports.push(rep)}catch(e){validationReports.push({_file:file,error:e.message,importacao:{ARQUIVO_NOME:file.name,STATUS:'REJEITADO',LINHAS_ACEITAS:0,LINHAS_QUARENTENA:0,CRITICOS:1,ALERTAS:0},ocorrencias:[]})}}renderValidationResults()}
function groupedIssues(issues){
 const map=new Map();for(const x of (issues||[])){const groupable=['FUNCIONARIO_NAO_CADASTRADO','LOCAL_AUSENTE','COLUNA_OPCIONAL_AUSENTE','PACOTE_NAO_CADASTRADO','PACOTE_SEM_CODIGO','PACOTE_DEPARA_NECESSARIO'].includes(x.TIPO),k=groupable?[x.SEVERIDADE,x.TIPO,x.CAMPO||'',x.VALOR||'',x.DETALHE||'',x.ACAO||''].join('|'):'ROW|'+(x.OCORRENCIA_ID||Math.random());const g=map.get(k)||{...x,_count:0,_dates:new Set(),_lines:[]};g._count++;if(x.DATA)g._dates.add(x.DATA);if(x.LINHA&&g._lines.length<5)g._lines.push(x.LINHA);map.set(k,g)}return [...map.values()].sort((a,b)=>{const p=x=>x.SEVERIDADE==='CRITICO'?0:x.SEVERIDADE==='ALERTA'?1:2;return p(a)-p(b)||b._count-a._count})}
function renderValidationResults(){const out=$('valResults');if(!out)return;out.innerHTML=validationReports.map((r,i)=>{const m=r.importacao||{},issues=r.ocorrencias||[],display=groupedIssues(issues),cls=statusClass(m.STATUS);return '<div class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>'+esc(m.ARQUIVO_NOME||r._file?.name)+'</h3><p>'+esc(r.error||('Hash '+String(m.ARQUIVO_HASH||'').slice(0,18)+'…'))+'</p></div>'+tag(m.STATUS,cls)+'</div><div class="validation-summary"><div><span>Aceitas</span><b>'+n(m.LINHAS_ACEITAS)+'</b></div><div><span>Quarentena</span><b>'+n(m.LINHAS_QUARENTENA)+'</b></div><div><span>Críticos</span><b>'+n(m.CRITICOS)+'</b></div><div><span>Alertas</span><b>'+n(m.ALERTAS)+'</b></div><div><span>Grupos a revisar</span><b>'+display.length+'</b></div><div><span>Período</span><b style="font-size:11px">'+fmtDate(m.DATA_INICIO)+'<br>'+fmtDate(m.DATA_FIM)+'</b></div></div>'+(display.length?'<div>'+display.slice(0,60).map(x=>{const dates=[...(x._dates||[])].sort(),where=x._count>1?(x._count+' ocorrências'+(dates.length?(' · '+dates.map(fmtDate).slice(0,3).join(', ')+(dates.length>3?'…':'')):'')+(x._lines?.length?(' · linhas '+x._lines.join(', ')):'') ):((x.DATA?fmtDate(x.DATA):'')+(x.LINHA?' · linha '+x.LINHA:''));const mapBtn=x.TIPO==='FUNCIONARIO_NAO_CADASTRADO'?'<div class="button-row compact"><button class="btn" onclick="ERP.mapEmployee('+i+','+JSON.stringify(String(x.VALOR||''))+','+JSON.stringify(String(x.NOME_ORIGEM||''))+')">Definir de/para</button></div>':'';return '<div class="issue"><div class="sev '+(x.SEVERIDADE==='CRITICO'?'crit':x.SEVERIDADE==='ALERTA'?'warn':'info')+'">'+esc(x.SEVERIDADE)+'</div><div><b>'+esc(x.TIPO)+'</b><p>'+esc(where)+'</p></div><div><b>'+esc(x.DETALHE||'')+'</b><p>'+esc(x.ACAO||'')+'</p>'+mapBtn+'</div></div>'}).join('')+'</div>':'<div class="empty">Nenhuma ocorrência relevante.</div>')+(!['REJEITADO','BLOQUEADO'].includes(m.STATUS)?'<div class="button-row"><button class="btn green" onclick="ERP.commitValidation('+i+')">Gravar no ERP / SharePoint</button></div>':'<div class="empty" style="margin-top:10px"><b>Importação bloqueada.</b> Corrija os itens críticos e valide o arquivo novamente.</div>')+'</div>'}).join('')}
function mapEmployee(i,oldMat,oldName){const funcs=(DATA.funcionarios||[]).filter(x=>norm(x.ATIVO||'SIM')!=='NAO');drawer('De/para de colaborador','<div class="form-card"><p><b>Origem histórica:</b><br>'+esc(oldMat)+' · '+esc(oldName||'nome não informado')+'</p><label>Vincular ao funcionário atual<select id="aliasTarget">'+options(funcs.map(x=>({value:x.MATRICULA,label:(x.MATRICULA||'')+' · '+x.NOME})),'','Selecione…')+'</select></label><div class="button-row"><button class="btn green" onclick="ERP.saveEmployeeAlias('+i+','+JSON.stringify(String(oldMat||''))+','+JSON.stringify(String(oldName||''))+')">Salvar de/para e revalidar</button></div><p class="muted" style="font-size:10px">A associação vale apenas para esta combinação de matrícula + nome histórico. Matrículas antigas com nomes diferentes continuam separadas para evitar vínculo incorreto.</p></div>','MIGRAÇÃO CONTROLADA')}
async function saveEmployeeAlias(i,oldMat,oldName){try{const target=$('aliasTarget')?.value;if(!target)throw new Error('Selecione o funcionário atual.');const alias={sourceMat:String(oldMat||''),sourceName:String(oldName||''),targetMat:String(target)},row={CHAVE:'ALIAS_FUNC-'+E.hash12(E.upper(oldMat)+'|'+E.upper(oldName)).toUpperCase(),VALOR:JSON.stringify(alias),DESCRICAO:(oldMat+' · '+oldName)+' → '+target,UPDATED_AT:new Date().toISOString()};await E.queue({key:'CONFIG-'+row.CHAVE,type:'GENERIC',payload:{operations:[{table:'config',rows:[row]}],audit:{action:'DEPARA_FUNCIONARIO',entityType:'CONFIG',entityId:row.CHAVE,after:alias,user:'',deviceId:E.deviceId()}},assets:[]});const idx=(DATA.config||[]).findIndex(x=>String(x.CHAVE)===row.CHAVE);if(idx>=0)DATA.config[idx]=row;else(DATA.config||(DATA.config=[])).push(row);await E.cacheTable('config',DATA.config);const current=validationReports[i];if(current?._file){const rep=await V.parseFile(current._file,validationCatalog());rep._file=current._file;validationReports[i]=rep}closeDrawer();renderValidationResults();toast('De/para salvo no aparelho e aplicado à validação.')}catch(e){toast(e.message)}}
async function commitValidation(i){const r=validationReports[i];if(!r)return;try{await E.commitImport(r,r._file);toast('Importação protegida no aparelho · sincronização automática');await loadData(false)}catch(e){toast(e.message)}}

function renderTools(){const tools=DATA.ferramentas||[],available=tools.filter(t=>toolStatus(t)==='DISPONIVEL').length,inuse=tools.filter(t=>toolStatus(t)==='EM USO').length,maint=tools.filter(t=>/MANUT|AVARI/.test(toolStatus(t))).length,open=openTerms().length;let h='<div class="hero"><div><small>MÓDULO 04</small><h2>Ferramentas / Almoxarifado</h2><p>Cada ativo tem número próprio. A saída registra funcionário, obra, pacote/frente, assinatura e condição; a devolução fecha o histórico sem apagar movimentações.</p></div></div>';
 h+='<div class="kpis">'+kpi('Cadastradas',tools.filter(t=>norm(t.ATIVO)==='SIM').length,'de '+tools.length+' posições','var(--navy)')+kpi('Disponíveis',available,'para retirada','var(--green)')+kpi('Em uso',inuse,'fora do almoxarifado','var(--amber)')+kpi('Manutenção/avaria',maint,'bloqueadas','var(--red)')+kpi('Termos abertos',open,'aguardando devolução','var(--blue)')+kpi('Fila offline',E.state.pending,'todas as operações','var(--orange)')+'</div>';
 h+='<div class="tabs"><button class="'+(toolTab==='inventory'?'on':'')+'" onclick="ERP.toolTab(\'inventory\')">Inventário</button><button class="'+(toolTab==='checkout'?'on':'')+'" onclick="ERP.toolTab(\'checkout\')">Registrar saída</button><button class="'+(toolTab==='return'?'on':'')+'" onclick="ERP.toolTab(\'return\')">Registrar devolução</button><button class="'+(toolTab==='history'?'on':'')+'" onclick="ERP.toolTab(\'history\')">Histórico</button></div>';
 if(toolTab==='inventory')h+=toolInventory();else if(toolTab==='checkout')h+=toolCheckoutForm();else if(toolTab==='return')h+=toolReturnForm();else h+=toolHistory();return h}
function toolInventory(){const L=(DATA.ferramentas||[]).slice().sort((a,b)=>n(a.NUMERO)-n(b.NUMERO));return '<div class="panel"><div class="panel-head"><div><h3>Patrimônio 001–050</h3><p>Itens ainda não cadastrados ficam bloqueados para retirada.</p></div></div><div class="tool-grid">'+L.map(t=>'<div class="tool-card" onclick="ERP.editTool(\''+esc(t.FERRAMENTA_ID)+'\')"><div class="tool-img">'+(t.FOTO_PRINCIPAL_URL||t.FOTO_REFERENCIA_URL?'<img loading="lazy" src="'+esc(imageSrc(t.FOTO_PRINCIPAL_URL||t.FOTO_REFERENCIA_URL))+'" alt="">':'IMAGEM PENDENTE')+'</div><div class="tool-copy"><span class="num">FER-'+String(n(t.NUMERO)).padStart(3,'0')+'</span><b>'+esc(t.NOME||'A cadastrar')+'</b><small>'+tag(t.STATUS,statusClass(t.STATUS))+' '+esc([t.MARCA,t.MODELO].filter(Boolean).join(' · '))+'</small></div></div>').join('')+'</div></div>'}
function options(arr,val,lab){return '<option value="">'+lab+'</option>'+arr.map(x=>'<option value="'+esc(x.value)+'"'+(String(x.value)===String(val)?' selected':'')+'>'+esc(x.label)+'</option>').join('')}
function toolCheckoutForm(){const funcs=(DATA.funcionarios||[]).filter(x=>norm(x.ATIVO||'SIM')!=='NAO'),packs=(DATA.pacotes||[]).filter(x=>!/(INATIV|ARQUIV)/.test(norm(x.STATUS))),works=[...new Set([...(DATA.obras||[]).filter(x=>norm(x.ATIVO||'SIM')!=='NAO').map(x=>x.NOME||x.OBRA),...DATA.apontamentos.map(x=>x.OBRA),...DATA.fvs.map(x=>x.OBRA)].filter(Boolean))].sort(),tools=(DATA.ferramentas||[]).filter(t=>toolStatus(t)==='DISPONIVEL'&&norm(t.ATIVO||'SIM')!=='NAO');return '<div class="form-card"><div class="panel-head"><div><h3>Novo termo de retirada</h3><p>A assinatura é salva primeiro no aparelho. Se a internet cair, o termo permanece pendente e sincroniza sozinho depois.</p></div></div><div class="form-grid"><label>Funcionário<select id="toEmp">'+options(funcs.map(x=>({value:x.MATRICULA,label:(x.MATRICULA||'')+' · '+x.NOME})),'','Selecione…')+'</select></label><label>Obra<select id="toObra">'+options(works.map(x=>({value:x,label:x})),'','Selecione…')+'</select></label><label>Pacote<select id="toPack">'+options(packs.map(x=>({value:x.CODIGO,label:x.CODIGO+' · '+x.PACOTE_SERVICO})),'','Selecione…')+'</select></label><label>Pavimento<input id="toPav" placeholder="Ex.: Térreo"></label><label class="wide">Local / frente<input id="toLocal" placeholder="Ex.: AP 101 · banheiro suíte"></label><label>Almoxarife<input id="toAlm" placeholder="Quem entregou"></label><label class="full">Observação<textarea id="toObs" placeholder="Opcional"></textarea></label></div><div class="panel-head" style="margin-top:14px"><div><h3>Ferramentas disponíveis</h3><p>'+tools.length+' disponíveis neste aparelho.</p></div></div><div class="check-grid">'+tools.map(t=>'<label class="check-item"><input type="checkbox" name="toolOut" value="'+esc(t.FERRAMENTA_ID)+'"><span><b>'+String(n(t.NUMERO)).padStart(3,'0')+' · '+esc(t.NOME)+'</b><small>'+esc(t.CONDICAO_ATUAL||'Condição não informada')+'</small></span></label>').join('')+'</div><div style="margin-top:14px"><b style="font-size:11px">Assinatura de quem retirou</b><div class="signature" id="signBox"><canvas id="signCanvas"></canvas><div class="signature-foot"><span>Assine com o dedo ou mouse</span><button class="btn" type="button" onclick="ERP.clearSignature()">Limpar</button></div></div></div><div class="button-row"><button class="btn green" onclick="ERP.checkoutTools()">Confirmar retirada</button></div></div>'}
function openTerms(){const terms=(DATA.termosFerramentas||[]).filter(t=>norm(t.STATUS)!=='FECHADO'),mov=DATA.movimentosFerramentas||[];return terms.map(t=>{const last=new Map();mov.filter(m=>String(m.TERMO_ID)===String(t.TERMO_ID)).sort((a,b)=>String(a.DATA_HORA).localeCompare(String(b.DATA_HORA))).forEach(m=>last.set(String(m.FERRAMENTA_ID),m));const open=[...last.values()].filter(x=>norm(x.TIPO)==='SAIDA');return {term:t,open}}).filter(x=>x.open.length)}
function toolReturnForm(){const ots=openTerms();if(!ots.length)return '<div class="empty">Nenhum termo aberto com ferramenta pendente de devolução.</div>';return '<div class="form-card"><div class="panel-head"><div><h3>Devolução</h3><p>Escolha um termo aberto. Cada ferramenta pode receber condição e foto da devolução.</p></div></div><label style="font:700 8px ui-monospace,monospace;color:#71849a">TERMO<select id="trTerm" onchange="ERP.renderReturnTerm()" style="display:block;width:100%;margin-top:5px;height:40px;border:1px solid var(--line);border-radius:9px">'+options(ots.map(x=>({value:x.term.TERMO_ID,label:fmtDT(x.term.DATA_HORA_SAIDA)+' · '+x.term.FUNCIONARIO_NOME+' · '+x.open.length+' item(ns)'})),'','Selecione…')+'</select></label><div id="returnTermBody" style="margin-top:12px"></div></div>'}
function renderReturnTerm(){const id=$('trTerm')?.value,ot=openTerms().find(x=>String(x.term.TERMO_ID)===String(id)),box=$('returnTermBody');if(!box)return;if(!ot){box.innerHTML='';return}box.innerHTML='<div class="detail-grid"><div><span>Funcionário</span><b>'+esc(ot.term.FUNCIONARIO_NOME)+'</b></div><div><span>Obra</span><b>'+esc(ot.term.OBRA)+'</b></div><div><span>Pacote</span><b>'+esc(ot.term.PACOTE_COD)+'</b></div></div><div style="margin-top:12px">'+ot.open.map(m=>'<div class="form-card" style="padding:11px"><label class="check-item"><input type="checkbox" name="toolReturn" value="'+esc(m.FERRAMENTA_ID)+'" checked><span><b>'+String(n(m.NUMERO)).padStart(3,'0')+' · '+esc(m.FERRAMENTA_NOME)+'</b><small>Retirada '+fmtDT(m.DATA_HORA)+'</small></span></label><div class="form-grid" style="margin-top:8px"><label>Condição<select id="cond_'+esc(m.FERRAMENTA_ID)+'"><option>OK</option><option>AVARIADA</option><option>MANUTENCAO</option><option>INCOMPLETA</option></select></label><label class="wide">Foto da devolução<input type="file" accept="image/*" id="photo_'+esc(m.FERRAMENTA_ID)+'"></label></div></div>').join('')+'</div><div class="form-grid"><label>Recebido por<input id="trReceiver" placeholder="Almoxarife"></label><label class="wide">Observação<input id="trObs" placeholder="Opcional"></label></div><div class="button-row"><button class="btn green" onclick="ERP.returnTools()">Confirmar devolução</button></div>'}
function toolHistory(){const M=rows('movimentosFerramentas').slice().sort((a,b)=>String(b.DATA_HORA).localeCompare(String(a.DATA_HORA)));return '<div class="panel"><div class="panel-head"><div><h3>Livro razão de ferramentas</h3><p>O histórico respeita os filtros globais. Abra o termo para consultar assinatura, saída, devolução e evidências.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Data/hora</th><th>Ferramenta</th><th>Movimento</th><th>Funcionário</th><th>Obra / pacote</th><th>Condição</th><th>Termo</th></tr></thead><tbody>'+M.map(x=>'<tr><td>'+fmtDT(x.DATA_HORA)+'</td><td><b>'+String(n(x.NUMERO)).padStart(3,'0')+' · '+esc(x.FERRAMENTA_NOME)+'</b></td><td>'+tag(x.TIPO,norm(x.TIPO)==='DEVOLUCAO'?'ok':'warn')+'</td><td>'+esc(x.FUNCIONARIO_NOME||'—')+'</td><td>'+esc(x.OBRA||'')+'<br><span class="muted">'+esc(x.PACOTE_COD||'')+'</span></td><td>'+tag(x.CONDICAO,statusClass(x.CONDICAO))+'</td><td><button class="link-btn" onclick="ERP.openToolTerm('+JSON.stringify(String(x.TERMO_ID||''))+')">'+esc(x.TERMO_ID||'—')+'</button></td></tr>').join('')+'</tbody></table></div></div>'}
function toolTermDetail(id){const t=(DATA.termosFerramentas||[]).find(x=>String(x.TERMO_ID)===String(id));if(!t)return '<div class="empty">Termo não localizado.</div>';const M=(DATA.movimentosFerramentas||[]).filter(x=>String(x.TERMO_ID)===String(id)).slice().sort((a,b)=>String(a.DATA_HORA).localeCompare(String(b.DATA_HORA))),last=new Map();M.forEach(x=>last.set(String(x.FERRAMENTA_ID),x));const pend=[...last.values()].filter(x=>norm(x.TIPO)==='SAIDA').length,sig=t.ASSINATURA_URL?'<figure class="signature-proof"><img src="'+esc(imageSrc(t.ASSINATURA_URL))+'" alt="Assinatura do responsável pela retirada"><figcaption>Assinatura registrada na retirada · hash '+esc(String(t.ASSINATURA_HASH||'').slice(0,16))+'…</figcaption></figure>':(t.ASSINATURA_HASH?'<div class="empty"><b>Assinatura protegida no aparelho.</b><br>O arquivo ficará disponível aqui após a sincronização com o SharePoint.</div>':'<div class="empty">Assinatura não localizada neste termo.</div>');return '<div class="detail-grid"><div><span>Termo</span><b>'+esc(t.TERMO_ID)+'</b></div><div><span>Status operacional</span><b>'+tag(pend?'ABERTO':'FECHADO',pend?'warn':'ok')+'</b></div><div><span>Saída</span><b>'+fmtDT(t.DATA_HORA_SAIDA)+'</b></div><div><span>Funcionário</span><b>'+esc((t.MATRICULA? t.MATRICULA+' · ':'')+(t.FUNCIONARIO_NOME||'—'))+'</b></div><div><span>Obra</span><b>'+esc(t.OBRA||'—')+'</b></div><div><span>Pacote / frente</span><b>'+esc((t.PACOTE_COD||'—')+' · '+(t.LOCAL_FRENTE||'—'))+'</b></div><div><span>Almoxarife</span><b>'+esc(t.RESPONSAVEL_ALMOXARIFADO||'—')+'</b></div><div><span>Itens ainda em uso</span><b>'+pend+'</b></div></div><div class="panel"><div class="panel-head"><div><h3>Comprovante de retirada</h3><p>A assinatura é evidência operacional vinculada ao termo e ao funcionário.</p></div></div>'+sig+'</div><div class="panel"><div class="panel-head"><div><h3>Movimentações do termo</h3><p>'+M.length+' evento(s) preservado(s) no livro razão.</p></div></div>'+(M.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Quando</th><th>Ferramenta</th><th>Mov.</th><th>Condição</th><th>Recebido por</th><th>Evidência</th></tr></thead><tbody>'+M.map(x=>'<tr><td>'+fmtDT(x.DATA_HORA)+'</td><td><b>'+String(n(x.NUMERO)).padStart(3,'0')+' · '+esc(x.FERRAMENTA_NOME)+'</b></td><td>'+tag(x.TIPO,norm(x.TIPO)==='DEVOLUCAO'?'ok':'warn')+'</td><td>'+tag(x.CONDICAO,statusClass(x.CONDICAO))+'</td><td>'+esc(x.RECEBIDO_POR||'—')+'</td><td>'+(x.FOTO_URL?'<a class="link-btn" href="'+esc(imageSrc(x.FOTO_URL))+'" target="_blank" rel="noopener">Ver foto</a>':'—')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Sem movimentações.</div>')+'</div>'}
function openToolTerm(id){drawer('Termo '+id,toolTermDetail(id),'ALMOXARIFADO · RASTREABILIDADE')}

function renderCad(){const packs=DATA.pacotes||[],funcs=DATA.funcionarios||[],fronts=DATA.frentes||[];return '<div class="hero"><div><small>CADASTROS MESTRES</small><h2>Uma única fonte de verdade.</h2><p>Pacotes e funcionários continuam compartilhados por Apontamento, FVS, Medição e Ferramentas. Frentes são geradas automaticamente pelos lançamentos.</p></div></div><div class="grid2"><div class="panel"><div class="panel-head"><div><h3>Pacotes</h3><p>'+packs.length+' cadastrados</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Serviço</th><th>Etapa</th><th>Status</th></tr></thead><tbody>'+packs.map(x=>'<tr><td><b>'+esc(x.CODIGO)+'</b></td><td>'+esc(x.PACOTE_SERVICO)+'</td><td>'+esc(x.ETAPA)+'</td><td>'+tag(x.STATUS,statusClass(x.STATUS))+'</td></tr>').join('')+'</tbody></table></div></div><div><div class="panel"><div class="panel-head"><div><h3>Funcionários</h3><p>'+funcs.length+' cadastrados</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Matrícula</th><th>Nome</th><th>Função</th></tr></thead><tbody>'+funcs.map(x=>'<tr><td>'+esc(x.MATRICULA)+'</td><td><b>'+esc(x.NOME)+'</b></td><td>'+esc(x.FUNCAO)+'</td></tr>').join('')+'</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Frentes de serviço</h3><p>'+fronts.length+' identificadores persistentes</p></div></div><small class="muted">FRENTE_ID = obra + pacote + pavimento + local normalizados.</small></div></div></div>'}
async function renderAdmin(){
  const q=await E.db.all('outbox').catch(()=>[]),blocked=q.filter(x=>x.blocked),aud=(DATA.auditoria||[]).slice().sort((a,b)=>String(b.DATA_HORA).localeCompare(String(a.DATA_HORA))).slice(0,80);
  const qrows=q.map(x=>{
    const actions=x.blocked?'<div class="button-row compact"><button class="btn" onclick="ERP.retryTx('+JSON.stringify(String(x.key))+')">Tentar novamente</button><button class="btn danger" onclick="ERP.discardTx('+JSON.stringify(String(x.key))+')">Descartar pendência</button></div>':'';
    return '<tr><td><b>'+esc(x.type)+'</b><br><span class="muted">'+esc(x.key)+'</span></td><td>'+tag(x.blocked?'CONFLITO':'PENDENTE',x.blocked?'bad':'warn')+'</td><td>'+fmtDT(x.createdAt)+'</td><td>'+n(x.attempts)+'</td><td><span class="danger-text">'+esc(x.lastError||'—')+'</span>'+actions+'</td></tr>';
  }).join('');
  const arows=aud.map(x=>'<tr><td>'+fmtDT(x.DATA_HORA)+'</td><td>'+tag(x.ACAO,'blue')+'</td><td>'+esc(x.ENTIDADE_TIPO)+'<br><span class="muted">'+esc(x.ENTIDADE_ID)+'</span></td><td>'+esc(x.USUARIO||'—')+'</td></tr>').join('');
  return '<div class="hero"><div><small>ADMINISTRAÇÃO TÉCNICA</small><h2>Saúde da sincronização e auditoria.</h2><p>Nenhuma pendência offline é descartada em silêncio. Falhas transitórias tentam novamente; conflitos de negócio ficam bloqueados para revisão humana, sem repetir indefinidamente.</p></div><div class="hero-actions"><button onclick="location.href=\'/auth/login?returnTo=/erp.html#administracao\'">Entrar novamente no Microsoft 365</button></div></div>'+ 
    '<div class="kpis">'+kpi('Versão','40.1.0','ERP','var(--navy)')+kpi('Online',navigator.onLine?'SIM':'NÃO','navegador',navigator.onLine?'var(--green)':'var(--red)')+kpi('Pendências',q.length,'outbox','var(--orange)')+kpi('Conflitos',blocked.length,'revisão necessária',blocked.length?'var(--red)':'var(--green)')+kpi('Último sync',E.state.lastOkAt?new Date(E.state.lastOkAt).toLocaleTimeString('pt-BR'):'—','sessão atual','var(--blue)')+kpi('Armazenamento',E.state.storagePersistent?'PROTEGIDO':'PADRÃO',E.state.storageQuota?((E.state.storageUsage/1048576).toFixed(1)+' MB usados'):'IndexedDB','var(--navy)')+'</div>'+ 
    '<div class="grid2"><div class="panel"><div class="panel-head"><div><h3>Outbox offline</h3><p>Transações aguardando SharePoint. Conflitos não são descartados nem repetidos automaticamente.</p></div></div>'+(q.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Tipo</th><th>Estado</th><th>Criada</th><th>Tentativas</th><th>Erro / ação</th></tr></thead><tbody>'+qrows+'</tbody></table></div>':'<div class="empty">Fila vazia. Todos os registros locais foram enviados.</div>')+'</div>'+ 
    '<div class="panel"><div class="panel-head"><div><h3>Auditoria</h3><p>Últimos eventos no ERP.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Quando</th><th>Ação</th><th>Entidade</th><th>Usuário</th></tr></thead><tbody>'+arows+'</tbody></table></div></div></div>';
}

function render(){if(loading)return;let h;if(PAGE==='dashboard')h=renderDashboard();else if(PAGE==='apontamentos')h=renderAp();else if(PAGE==='qualidade')h=renderQuality();else if(PAGE==='validacao')h=renderValidator();else if(PAGE==='ferramentas')h=renderTools();else if(PAGE==='cadastros')h=renderCad();else{$('content').innerHTML='<div class="loading-card">Abrindo administração…</div>';renderAdmin().then(x=>$('content').innerHTML=x);return}$('content').innerHTML=h;if(PAGE==='validacao')bindValidator();if(PAGE==='ferramentas'&&toolTab==='checkout')setTimeout(initSignature,0);if(PAGE==='ferramentas'&&toolTab==='return')setTimeout(renderReturnTerm,0)}

function frontDetail(id){const g=consolidate().find(x=>String(x.id)===String(id));if(!g)return'<div class="empty">Frente não localizada no recorte atual.</div>';const q=fvsState(g),rec=q.rec,items=rec?(DATA.fvsItens||[]).filter(x=>String(x.REGISTRO_ID)===String(rec.ID)):[],photos=rec?(DATA.fotos||[]).filter(x=>String(x.REGISTRO_ID)===String(rec.ID)):g.photos,meds=g.med.slice().sort((a,b)=>String(b.DATA).localeCompare(String(a.DATA))),open=toolsOpen(g.mov);let h=(g.unresolved?'<div class="panel" style="border-left:4px solid var(--amber)"><b>Frente não identificada automaticamente</b><p class="muted">Este apontamento não possui pavimento/local suficiente. Ele permanece na produção, mas não é vinculado automaticamente a FVS, medição ou ferramentas para evitar associação incorreta.</p></div>':'')+'<div class="detail-grid"><div><span>Obra</span><b>'+esc(g.obra||'—')+'</b></div><div><span>Pacote</span><b>'+esc(g.pac+' · '+(g.serv||''))+'</b></div><div><span>Local</span><b>'+esc([g.pav,g.local].filter(Boolean).join(' · ')||'—')+'</b></div><div><span>Dias-homem</span><b>'+num(g.dh)+'</b></div><div><span>Pessoas</span><b>'+g.pessoas.size+'</b></div><div><span>Conferido</span><b>'+tag(q.label,q.cls)+'</b></div></div>';
 h+='<div class="panel"><div class="panel-head"><div><h3>Qualidade</h3><p>'+(rec?'FVS '+esc(rec.ID):'Nenhuma FVS vinculada')+'</p></div></div>'+(rec?'<div class="detail-grid"><div><span>Data</span><b>'+fmtDate(rec.DATA)+'</b></div><div><span>Responsável</span><b>'+esc(rec.RESPONSAVEL||'—')+'</b></div><div><span>Situação</span><b>'+tag(rec.SITUACAO,statusClass(rec.SITUACAO))+'</b></div><div><span>Conformes</span><b>'+n(rec.CONFORMES)+'</b></div><div><span>Não conformes</span><b>'+n(rec.NAO_CONFORMES)+'</b></div><div><span>Pendentes</span><b>'+n(rec.PENDENTES)+'</b></div></div>'+(items.length?'<div class="table-wrap" style="margin-top:10px"><table class="data-table"><thead><tr><th>Item</th><th>Verificação</th><th>Critério</th><th>Status</th><th>Obs.</th></tr></thead><tbody>'+items.map(x=>'<tr><td>'+n(x.ITEM)+'</td><td><b>'+esc(x.VERIFICACAO)+'</b></td><td>'+esc(x.CRITERIO)+'</td><td>'+tag(x.STATUS,statusClass(x.STATUS))+'</td><td>'+esc(x.OBSERVACAO||'—')+'</td></tr>').join('')+'</tbody></table></div>':''):'<div class="empty">Serviço ainda não conferido por FVS.</div>')+'</div>';
 h+='<div class="panel"><div class="panel-head"><div><h3>Evidências fotográficas</h3><p>'+photos.length+' foto(s) vinculada(s)</p></div></div>'+(photos.length?'<div class="photo-gallery">'+photos.map(x=>'<figure><a href="'+esc(imageSrc(x.ARQUIVO_URL))+'" target="_blank" rel="noopener"><img loading="lazy" src="'+esc(imageSrc(x.ARQUIVO_URL))+'" alt="Foto FVS"></a><figcaption>'+esc(x.ITEM?('Item '+x.ITEM+' · '):'')+esc(x.LEGENDA||x.ARQUIVO_NOME||'Evidência')+'</figcaption></figure>').join('')+'</div>':'<div class="empty">Sem fotografia sincronizada.</div>')+'</div>';
 h+='<div class="split"><div class="panel"><div class="panel-head"><div><h3>Medição física</h3></div></div>'+(meds.length?meds.map(x=>'<div class="detail-grid"><div><span>Executado</span><b>'+pct(x.EXECUTADO_PCT)+'</b></div><div><span>Aprovado FVS</span><b>'+pct(x.APROVADO_PCT)+'</b></div><div><span>Acumulado</span><b>'+pct(x.ACUMULADO_PCT)+'</b></div></div>').join(''):'<div class="empty">Sem medição vinculada.</div>')+'</div><div class="panel"><div class="panel-head"><div><h3>Ferramentas</h3><p>'+open.length+' ainda em uso</p></div></div>'+(g.mov.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Ferramenta</th><th>Mov.</th><th>Quando</th><th>Funcionário</th><th>Termo</th></tr></thead><tbody>'+g.mov.slice().sort((a,b)=>String(b.DATA_HORA).localeCompare(String(a.DATA_HORA))).map(x=>'<tr><td><b>'+String(n(x.NUMERO)).padStart(3,'0')+' · '+esc(x.FERRAMENTA_NOME)+'</b></td><td>'+tag(x.TIPO,norm(x.TIPO)==='DEVOLUCAO'?'ok':'warn')+'</td><td>'+fmtDT(x.DATA_HORA)+'</td><td>'+esc(x.FUNCIONARIO_NOME||'—')+'</td><td><button class="link-btn" onclick="ERP.openToolTerm('+JSON.stringify(String(x.TERMO_ID||''))+')">'+esc(x.TERMO_ID||'—')+'</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Nenhuma ferramenta vinculada à frente.</div>')+'</div></div>';return h}
