function editTool(id){const t=(DATA.ferramentas||[]).find(x=>String(x.FERRAMENTA_ID)===String(id));if(!t)return;const q=encodeURIComponent([t.NOME,t.MARCA,t.MODELO].filter(Boolean).join(' '));drawer(String(n(t.NUMERO)).padStart(3,'0')+' · '+(t.NOME||'A cadastrar'),'<div class="form-card"><div class="form-grid"><label>Número<input value="'+esc(t.NUMERO)+'" disabled></label><label class="wide">Nome<input id="edName" value="'+esc(t.NOME||'')+'" placeholder="Ex.: Martelete"></label><label>Categoria<input id="edCat" value="'+esc(t.CATEGORIA||'')+'"></label><label>Marca<input id="edBrand" value="'+esc(t.MARCA||'')+'"></label><label>Modelo<input id="edModel" value="'+esc(t.MODELO||'')+'"></label><label>Nº série<input id="edSerial" value="'+esc(t.NUMERO_SERIE||'')+'"></label><label>Status<select id="edStatus"><option>DISPONIVEL</option><option>EM USO</option><option>MANUTENCAO</option><option>AVARIADA</option><option>EXTRAVIADA</option><option>BAIXADA</option><option>CADASTRO PENDENTE</option></select></label><label>Condição<input id="edCond" value="'+esc(t.CONDICAO_ATUAL||'')+'"></label><label>Ativo<select id="edActive"><option>SIM</option><option>NAO</option></select></label><label class="wide">Foto real<input id="edPhoto" type="file" accept="image/*"></label><label class="full">URL imagem de referência<input id="edRef" value="'+esc(t.FOTO_REFERENCIA_URL||'')+'" placeholder="Cole a URL da imagem de referência"></label><label class="full">Origem da referência<input id="edRefOrigin" value="'+esc(t.FOTO_REFERENCIA_ORIGEM||'')+'" placeholder="URL da página/fabricante"></label><label class="full">Observação<textarea id="edObs">'+esc(t.OBSERVACAO||'')+'</textarea></label></div><div class="button-row"><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q='+q+'">Pesquisar imagem de referência</a><button class="btn green" onclick="ERP.saveTool(\''+esc(id)+'\')">Salvar ferramenta</button></div><p class="muted" style="font-size:9px">Uma imagem da internet é tratada como referência. A foto real do patrimônio, quando cadastrada, tem prioridade.</p></div>','CADASTRO DE FERRAMENTA');setTimeout(()=>{$('edStatus').value=t.STATUS||'CADASTRO PENDENTE';$('edActive').value=t.ATIVO||'NAO'},0)}
async function saveTool(id){const t=(DATA.ferramentas||[]).find(x=>String(x.FERRAMENTA_ID)===String(id));if(!t)return;const row={...t,NOME:$('edName').value,CATEGORIA:$('edCat').value,MARCA:$('edBrand').value,MODELO:$('edModel').value,NUMERO_SERIE:$('edSerial').value,STATUS:$('edStatus').value,CONDICAO_ATUAL:$('edCond').value,ATIVO:$('edActive').value,FOTO_REFERENCIA_URL:$('edRef').value,FOTO_REFERENCIA_ORIGEM:$('edRefOrigin').value,OBSERVACAO:$('edObs').value,UPDATED_AT:new Date().toISOString()},payload={operations:[{table:'ferramentas',rows:[row]}],audit:{action:'ATUALIZAR_FERRAMENTA',entityType:'FERRAMENTA',entityId:id,after:row,user:'',deviceId:E.deviceId()}},assets=[];const f=$('edPhoto').files?.[0];if(f){const key=await E.saveAsset(f,{name:id+'.jpg',folder:'Ferramentas/Catalogo'});assets.push({assetKey:key,folder:'Ferramentas/Catalogo',name:id+'.jpg',target:'operations.0.rows.0.FOTO_PRINCIPAL_URL'})}await E.queue({key:'TOOL-MASTER-'+id,type:'GENERIC',payload,assets});Object.assign(t,row);await E.cacheTable('ferramentas',DATA.ferramentas);closeDrawer();toast('Ferramenta salva no aparelho');render()}
function initSignature(){const c=$('signCanvas');if(!c)return;const rect=c.getBoundingClientRect(),dpr=Math.max(1,devicePixelRatio||1);c.width=Math.round(rect.width*dpr);c.height=Math.round(170*dpr);const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#112b49';let down=false,empty=true;const pos=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:p.clientX-r.left,y:p.clientY-r.top}};const start=e=>{e.preventDefault();down=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)};const move=e=>{if(!down)return;e.preventDefault();const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();empty=false};const end=()=>{down=false};c.onpointerdown=start;c.onpointermove=move;c.onpointerup=end;c.onpointercancel=end;signature={canvas:c,ctx,isEmpty:()=>empty,clear:()=>{ctx.clearRect(0,0,rect.width,170);empty=true}}}
function clearSignature(){signature?.clear()}
async function canvasBlob(c){return new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(new Error('Falha ao gerar assinatura.')),'image/png'))}
async function checkoutTools(){try{const mat=$('toEmp').value,emp=(DATA.funcionarios||[]).find(x=>String(x.MATRICULA)===String(mat)),obra=$('toObra').value,code=$('toPack').value,pack=currentPackage(code),ids=[...document.querySelectorAll('input[name=toolOut]:checked')].map(x=>x.value),tools=ids.map(id=>(DATA.ferramentas||[]).find(t=>String(t.FERRAMENTA_ID)===id)).filter(Boolean);if(!emp)throw new Error('Selecione o funcionário.');if(!obra)throw new Error('Selecione a obra.');if(!pack.CODIGO)throw new Error('Selecione o pacote.');if(!norm($('toLocal').value))throw new Error('Informe o local / frente de uso.');if(!norm($('toAlm').value))throw new Error('Informe quem entregou no almoxarifado.');if(!tools.length)throw new Error('Selecione pelo menos uma ferramenta.');if(!signature||signature.isEmpty())throw new Error('A assinatura de quem retirou é obrigatória.');const sig=await canvasBlob(signature.canvas),r=await E.toolCheckout({employee:{id:E.employeeId(emp.MATRICULA),matricula:emp.MATRICULA,nome:emp.NOME},obra,pacote:{codigo:pack.CODIGO,nome:pack.PACOTE_SERVICO,etapa:pack.ETAPA},pavimento:$('toPav').value,local:$('toLocal').value,almoxarife:$('toAlm').value,observacao:$('toObs').value,tools,signatureBlob:sig});DATA.termosFerramentas.push(r.term);DATA.movimentosFerramentas.push(...(r.movements||[]));for(const t of tools)t.STATUS='EM USO';await Promise.all([E.cacheTable('ferramentas',DATA.ferramentas),E.cacheTable('termosFerramentas',DATA.termosFerramentas),E.cacheTable('movimentosFerramentas',DATA.movimentosFerramentas)]);toast('Retirada registrada offline ✓');toolTab='history';render();updateStatus()}catch(e){toast(e.message)}}
async function returnTools(){try{const id=$('trTerm').value,ot=openTerms().find(x=>String(x.term.TERMO_ID)===String(id));if(!ot)throw new Error('Selecione o termo.');const ids=[...document.querySelectorAll('input[name=toolReturn]:checked')].map(x=>x.value);if(!ids.length)throw new Error('Selecione ao menos uma ferramenta.');if(!norm($('trReceiver').value))throw new Error('Informe quem recebeu a devolução.');const items=[];for(const tid of ids){const base=(DATA.ferramentas||[]).find(x=>String(x.FERRAMENTA_ID)===String(tid))||ot.open.find(x=>String(x.FERRAMENTA_ID)===String(tid))||{};items.push({...base,returnCondition:document.getElementById('cond_'+tid)?.value||'OK',photoBlob:document.getElementById('photo_'+tid)?.files?.[0]||null})}const rr=await E.toolReturn({termId:id,items,employeeId:ot.term.FUNCIONARIO_ID,employeeName:ot.term.FUNCIONARIO_NOME,obraId:ot.term.OBRA_ID,obra:ot.term.OBRA,frenteId:ot.term.FRENTE_ID,pacoteCod:ot.term.PACOTE_COD,pacoteServico:ot.term.PACOTE_SERVICO,pavimento:ot.term.PAVIMENTO,local:ot.term.LOCAL_FRENTE,recebidoPor:$('trReceiver').value,observacao:$('trObs').value});DATA.movimentosFerramentas.push(...(rr.movements||[]));for(const t of items){const x=(DATA.ferramentas||[]).find(y=>String(y.FERRAMENTA_ID)===String(t.FERRAMENTA_ID));if(x)x.STATUS=/AVARI/.test(norm(t.returnCondition))?'AVARIADA':/MANUT/.test(norm(t.returnCondition))?'MANUTENCAO':'DISPONIVEL'}await Promise.all([E.cacheTable('ferramentas',DATA.ferramentas),E.cacheTable('movimentosFerramentas',DATA.movimentosFerramentas)]);toast('Devolução protegida no aparelho ✓');toolTab='history';render();updateStatus()}catch(e){toast(e.message)}}

