async function discardTx(key){if(!confirm('Descartar esta pendência local? Use apenas quando o conflito já estiver resolvido ou o lançamento não deva mais ser enviado.'))return;try{await E.discardTransaction(key);toast('Pendência descartada. Recarregando o estado central…');await loadData(true)}catch(e){toast(e.message)}}
